// Builds src/data/positions.json by constructing every position from source
// data and verifying that the listed move is legal and delivers mate-in-1.
// Historical classics are generated by playing their game fragments through
// chess.js. Lichess puzzles are generated from the database row convention:
// source FEN before setup move, then setup UCI, then one solver UCI.

import { readFileSync, writeFileSync } from "node:fs";
import { Chess } from "chess.js";

const LICHESS_SOURCE_PATH = "src/data/lichess-mate-in-1-sources.json";
const OUT_PATH = "src/data/positions.json";

function playedFrom(moves) {
  const chess = new Chess();
  for (const move of moves) chess.move(move);
  return chess.fen();
}

function uciToMove(uci) {
  if (!/^[a-h][1-8][a-h][1-8][qrbn]?$/.test(uci)) throw new Error(`invalid UCI move '${uci}'`);
  const move = { from: uci.slice(0, 2), to: uci.slice(2, 4) };
  if (uci.length === 5) move.promotion = uci[4];
  return move;
}

function verifyEntry(entry) {
  const chess = new Chess(entry.fen);
  if (chess.turn() !== entry.sideToMove) {
    throw new Error(`${entry.id}: sideToMove '${entry.sideToMove}' does not match FEN turn '${chess.turn()}'`);
  }
  const legal = chess.moves({ square: entry.solution.from, verbose: true });
  const target = legal.find((m) => (
    m.to === entry.solution.to
    && (!entry.solution.promotion || m.promotion === entry.solution.promotion)
  ));
  if (!target) throw new Error(`${entry.id}: solution is not legal`);
  chess.move(entry.solution);
  if (!chess.isCheckmate()) throw new Error(`${entry.id}: solution did not deliver mate`);
}

function lichessCredit(row) {
  return `From a real game · lichess.org/puzzle/${row.puzzleId}`;
}

function buildLichessEntry(row) {
  const moves = Array.isArray(row.moves) ? row.moves : String(row.moves).trim().split(/\s+/);
  if (moves.length !== 2) throw new Error(`${row.puzzleId}: expected setup + one mate move, got ${moves.length}`);

  const chess = new Chess(row.fen);
  const setup = chess.move(uciToMove(moves[0]));
  if (!setup) throw new Error(`${row.puzzleId}: setup move ${moves[0]} is illegal`);

  const fen = chess.fen();
  const sideToMove = chess.turn();
  if (fen.split(" ")[1] !== sideToMove) throw new Error(`${row.puzzleId}: post-setup side-to-move mismatch`);

  const solution = uciToMove(moves[1]);
  const entry = {
    id: `lichess-${row.puzzleId}`,
    title: "Mate in 1",
    credit: lichessCredit(row),
    fen,
    sideToMove,
    solution,
  };
  verifyEntry(entry);
  return entry;
}

const historical = [
  {
    id: "fools-mate-1836",
    title: "Fool's mate",
    credit: "Traditional; earliest published 1836",
    fen: playedFrom(["f3", "e5", "g4"]),
    sideToMove: "b",
    solution: { from: "d8", to: "h4" },
  },
  {
    id: "scholars-mate-1656",
    title: "Scholar's mate",
    credit: "Francis Beale, 1656",
    fen: playedFrom(["e4", "e5", "Bc4", "Nc6", "Qh5", "Nf6"]),
    sideToMove: "w",
    solution: { from: "h5", to: "f7" },
  },
  {
    id: "legal-mate-1750",
    title: "Legal's mate",
    credit: "Kermur de Legal, c. 1750",
    fen: playedFrom(["e4", "e5", "Nf3", "d6", "Bc4", "Bg4", "Nc3", "g6", "Nxe5", "Bxd1", "Bxf7+", "Ke7"]),
    sideToMove: "w",
    solution: { from: "c3", to: "d5" },
  },
  {
    id: "opera-house-final",
    title: "Opera-house mate",
    credit: "Morphy vs Duke Karl & Count Isouard, Paris 1858",
    fen: playedFrom([
      "e4", "e5", "Nf3", "d6", "d4", "Bg4", "dxe5", "Bxf3", "Qxf3", "dxe5",
      "Bc4", "Nf6", "Qb3", "Qe7", "Nc3", "c6", "Bg5", "b5", "Nxb5", "cxb5",
      "Bxb5+", "Nbd7", "O-O-O", "Rd8", "Rxd7", "Rxd7", "Rd1", "Qe6", "Bxd7+",
      "Nxd7", "Qb8+", "Nxb8",
    ]),
    sideToMove: "w",
    solution: { from: "d1", to: "d8" },
  },
];

for (const entry of historical) verifyEntry(entry);

const lichessRows = JSON.parse(readFileSync(LICHESS_SOURCE_PATH, "utf8"));
const seenFens = new Set(historical.map((entry) => entry.fen));
const lichess = [];
for (const row of lichessRows) {
  const entry = buildLichessEntry(row);
  if (seenFens.has(entry.fen)) throw new Error(`${entry.id}: duplicate FEN in shelf`);
  seenFens.add(entry.fen);
  lichess.push(entry);
}

const shipped = [...historical, ...lichess];

// Greedy transition-density ordering: start from the first entry, then
// repeatedly choose the remaining position with the maximum square-grid delta.
function pieceGrid(fen) {
  const rows = fen.split(" ")[0].split("/");
  let out = "";
  for (const row of rows) {
    for (const ch of row) {
      if (/\d/.test(ch)) out += " ".repeat(Number(ch));
      else out += ch;
    }
  }
  return out;
}

function squareDelta(a, b) {
  let d = 0;
  for (let i = 0; i < 64; i++) if (a[i] !== b[i]) d++;
  return d;
}

const ordered = [shipped[0]];
const pool = shipped.slice(1);
while (pool.length) {
  const currentGrid = pieceGrid(ordered[ordered.length - 1].fen);
  let bestIdx = 0;
  let bestDelta = -1;
  for (let i = 0; i < pool.length; i++) {
    const d = squareDelta(currentGrid, pieceGrid(pool[i].fen));
    if (d > bestDelta) {
      bestDelta = d;
      bestIdx = i;
    }
  }
  ordered.push(pool.splice(bestIdx, 1)[0]);
}

for (const entry of ordered) verifyEntry(entry);

let totalDelta = 0;
for (let i = 1; i < ordered.length; i++) {
  totalDelta += squareDelta(pieceGrid(ordered[i - 1].fen), pieceGrid(ordered[i].fen));
}

writeFileSync(OUT_PATH, JSON.stringify(ordered, null, 2) + "\n");
console.log(`Wrote ${OUT_PATH} — ${ordered.length} verified mate-in-1 positions (${lichess.length} from Lichess).`);
console.log(`Adjacent-position square-delta mean ${(totalDelta / (ordered.length - 1)).toFixed(1)}.`);
